replicas = {
    "replica_1": {"chunk_5": "original text"},
    "replica_2": {"chunk_5": "original text"},
    "replica_3": {"chunk_5": "original text"},
}

def asynchronous_write(replicas, key, new_value, lagging_replica=None):
    # writes propagate to every replica except the one that is lagging
    for replica_name, store in replicas.items():
        if replica_name == lagging_replica:
            print(f"  {replica_name}: write delayed")
            continue
        store[key] = new_value
        print(f"  {replica_name}: updated to {new_value!r}")

print("Writing an update, but replica_3 lags behind:")
asynchronous_write(replicas, "chunk_5", "updated text", lagging_replica="replica_3")

print("\nReading from each replica immediately after the write:")
for replica_name, store in replicas.items():
    print(f"  {replica_name}: {store['chunk_5']!r}")
